function speak(text){if(!('speechSynthesis' in window))return alert('Speech synthesis is not available in this browser.');speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang=state.accent;const voices=speechSynthesis.getVoices();u.voice=voices.find(v=>v.lang===state.accent)||voices.find(v=>v.lang?.startsWith(state.accent.slice(0,2)))||null;u.rate=state.accent==='en-AU'?.94:.96;speechSynthesis.speak(u)}

